+Deno.test('deploy prebuild emits Aspire-normalized browser keys', () => {
+  const env = buildVitePrebuildEnvironment(
+    {
+      'sagas-api': { port: 7101 },
+      'orders.api': { port: 7102 },
+    },
+    {
+      'workers.api/v2': { enabled: true, port: 7201 },
+      'disabled-api': { enabled: false, port: 7202 },
+    },
+  );
+
