// IMPL-EVAL scratch: corpus-sufficiency demonstration for #1833/PR #1835.
// Simulates one-sided mutations of the SDK's identifier-segment rule and
// reports which corpus entries would catch each. No repo code is modified.

import { buildViteEnvVarName } from '@netscript/aspire/application';

// Corpus replicated verbatim from packages/sdk/tests/discovery/env-ordering_test.ts:25-41.
const ASCII_PUNCTUATION = Array.from(
  { length: 0x7e - 0x21 + 1 },
  (_, index) => String.fromCharCode(0x21 + index),
).filter((c) => !/[a-zA-Z0-9_]/.test(c));
const CORPUS = [
  ...ASCII_PUNCTUATION.flatMap((c) => [`${c}alpha`, `alpha${c}omega`, `alpha${c}`]),
  'a__b',
  ' orders api ',
  '\torders\napi\r',
  '',
  '1orders',
];

// Real rules (as shipped).
const canon = (v: string) => v.replace(/[^a-zA-Z0-9_]/g, '_');
const sdkFull = (n: string, proto = 'http', i = 0) =>
  `VITE_services__${canon(n)}__${proto}__${i}`;
const sdkShort = (n: string) => `VITE_${canon(n).toUpperCase()}_URL`;

// One-sided mutations a future regression could introduce on the SDK side only.
const MUTANTS: Record<string, (v: string) => string> = {
  'collapse consecutive underscores': (v) => canon(v).replace(/_{2,}/g, '_'),
  'strip leading digits': (v) => canon(v).replace(/^\d+/, ''),
  'strip trailing underscores': (v) => canon(v).replace(/_+$/, ''),
  'pre-#1833 hyphen-only rule': (v) => v.toUpperCase().replace(/-/g, '_'),
};

let allCaught = true;
for (const [name, mutate] of Object.entries(MUTANTS)) {
  const caughtFull = CORPUS.filter((n) => `VITE_services__${mutate(n)}__http__0` !== buildViteEnvVarName(n).full);
  const caughtShort = CORPUS.filter((n) => `VITE_${mutate(n).toUpperCase()}_URL` !== buildViteEnvVarName(n).shorthand);
  const caught = new Set([...caughtFull, ...caughtShort]);
  const status = caught.size > 0 ? 'CAUGHT' : 'SURVIVES CORPUS';
  if (caught.size === 0) allCaught = false;
  console.log(`${status}  ${name}  (catching inputs: ${caught.size})  e.g. ${[...caught].slice(0, 3).map(JSON.stringify).join(', ') || 'n/a'}`);
}
console.log(allCaught ? '\n=> every simulated one-sided mutation is caught by the corpus' : '\n=> gap found');

// Adversarial sweep beyond the corpus against the REAL repo functions is done
// separately by the evaluator harness; here assert canonical identity holds
// for inputs outside the corpus (unicode, underscore edge cases).
const EXTRA = ['__x', 'x__', '_a_', 'naïve-名前', 'a🎉b', 'a_.b', 'A-9_z.w/v'];
for (const n of EXTRA) {
  const okF = sdkFull(n) === buildViteEnvVarName(n).full;
  const okS = sdkShort(n) === buildViteEnvVarName(n).shorthand;
  if (!okF || !okS) console.log(`DIVERGENCE beyond corpus: ${JSON.stringify(n)} full=${okF} short=${okS}`);
}
console.log('extra-sweep done (silent = no divergence beyond corpus)');

